<fieldset class="opts"><legend>{{$.t.time}}</legend><div class="slots" id="slots" aria-live="polite" data-none="{{$.t.no_slots}}" data-loading="{{$.t.loading}}"></div></fieldset>
{{if $.user}}<fieldset class="group details"><legend>{{$.t.your_details}}</legend><div class="pair">
<div class="field"><label for="name">{{$.t.name}}</label><input id="name" name="name" value="{{$.custName}}" required autocomplete="name"></div>
<div class="field"><label for="phone">{{$.t.phone}}</label><input id="phone" name="phone" type="tel" value="{{$.custPhone}}" placeholder="+971 50 123 4567" required autocomplete="tel" dir="ltr"></div></div></fieldset>
{{template "payment" $}}
<div class="buybar"><span class="buybar-sum"><span class="price">{{.price}}</span><span class="chosen" id="chosen" data-fmt="{{$.t.date_time}}">{{$.t.choose_time}}</span></span><button class="btn" id="go" disabled>{{$.t.confirm_booking}}</button></div>
{{else}}<p class="quiet signin-hint">{{$.t.sign_in_hint}}</p>
<div class="buybar"><span class="buybar-sum"><span class="price">{{.price}}</span><span class="chosen" id="chosen" data-fmt="{{$.t.date_time}}">{{$.t.choose_time}}</span></span><a class="btn" href="/_rx/auth/login?next={{$.here}}">{{$.t.sign_in_to_book}}</a></div>{{end}}
</form></div></div>
<script>
(function(){var p=document.getElementById('picker'),box=document.getElementById('slots'),t=document.getElementById('time'),go=document.getElementById('go'),ch=document.getElementById('chosen'),PICK=ch?ch.textContent:'';
document.body.classList.add('has-buybar');
function val(n){var r=p.querySelector('input[name="'+n+'"]:checked');return r?r.value:''}
function msg(s){var e=document.createElement('p');e.className='slots-note';e.textContent=s;box.textContent='';box.appendChild(e)}
function load(){t.value='';if(go)go.disabled=true;if(ch)ch.textContent=PICK;msg(box.dataset.loading);
var d=val('date'),r=p.querySelector('input[name="date"]:checked'),lab=r?r.dataset.label:'';
if(!d){msg(box.dataset.none);return}
fetch('/api/slots?service='+p.dataset.service+'&staff='+encodeURIComponent(val('staff'))+'&date='+encodeURIComponent(d)).then(function(x){return x.json()}).then(function(j){
if(val('date')!==d)return;if(!j.slots||!j.slots.length){msg(box.dataset.none);return}box.textContent='';
j.slots.forEach(function(x){var b=document.createElement('button');b.type='button';b.className='slot';b.textContent=x.time;b.setAttribute('aria-pressed','false');
b.onclick=function(){t.value=x.time;[].forEach.call(box.querySelectorAll('.slot'),function(c){c.setAttribute('aria-pressed','false')});b.setAttribute('aria-pressed','true');if(go)go.disabled=false;if(ch)ch.textContent=(ch.dataset.fmt||'{date}, {time}').replace('{date}',lab).replace('{time}',x.time)};box.appendChild(b)})
}).catch(function(){msg(box.dataset.none)})}
p.addEventListener('change',function(e){if(e.target.name==='staff'||e.target.name==='date')load()});load()})();
</script>{{end}}{{template "bottom" .}}

