scripts.pay_again:
// POST /bookings/:id/pay (signed in): pay a booking that is still waiting for its card payment
function handle(req) {
  const lang = req.form.lang === 'ar' ? 'ar' : 'en', q = lang === 'ar' ? '&lang=ar' : '';
  const id = Number(req.params.id);
  const o = db.query('SELECT * FROM bookings WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!o) return {template: 'not_found', data: page(req, {title: texts(langOf(req)).not_found_title}), status: 404};
  if (o.status !== 'pending' || o.payment_method !== 'card') return {redirect: '/bookings/' + id + (lang === 'ar' ? '?lang=ar' : '')};
  // The hold lasts an hour; after that the time or seat may have gone to someone else.
  let free = false;
  if (o.kind === 'class') {
    const c = db.query('SELECT * FROM classes WHERE id = ? AND active = 1', o.class_id)[0];
    free = !!c && (seatsTaken(id)[c.id] || 0) < c.capacity;
  } else {
    const s = db.query('SELECT * FROM services WHERE id = ?', o.service_id)[0];
    free = !!s && freeSlots(business(), s, o.staff_id, o.date, id).some(x => x.time === o.time);
  }
  if (!free) {
    db.exec("UPDATE bookings SET status = 'expired' WHERE id = ?", id);
    return {redirect: '/bookings/' + id + '?error=error_slot' + q};
  }
  return proceed(req, id, lang);
}

