scripts.on_payment:
// Runs when a card payment is paid, fails or expires, is refunded (by a script, on the Payments page or in Stripe), and
// for monthly enrolments when a month is renewed, a renewal fails or the subscription ends.
// req.body: {event, id, reference, amount, refunded_amount, subscription, period, ...}
function handle(req) {
  const id = Number(String(req.body.reference).replace('booking-', ''));
  const o = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
  if (!o) return {text: 'ignored'};
  const ev = req.body.event, sub = req.body.subscription && typeof req.body.subscription === 'object' ? req.body.subscription : null;
  if (ev === 'refunded' || ev === 'partially_refunded') {
    // Record the amount refunded; the status stays (a cancelled booking stays cancelled). Only a booking that is still
    // on and is refunded in full is marked refunded, which frees its time or seat. A refunded month of a monthly
    // enrolment does not end it.
    recordRefund(id, req.body.id, req.body.refunded_amount || 0);
    const now = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
    if (ev === 'refunded' && !isMonthly(o) && (now.status === 'confirmed' || now.status === 'pending') && (now.paid_amount || 0) <= 0) {
      db.exec("UPDATE bookings SET status = 'refunded' WHERE id = ?", id);
    }
    console.log('booking ' + id + ' ' + ev + ' ' + req.body.refunded_amount);
    return {text: 'ok'};
  }
  if (ev === 'renewed') {
    db.exec("UPDATE bookings SET paid_amount = ?, paid_until = ?, sub_status = CASE WHEN sub_status = 'ending' THEN 'ending' ELSE 'active' END WHERE id = ?",
      round2((o.paid_amount || 0) + (req.body.amount || 0)), sub ? sub.current_period_end || '' : o.paid_until || '', id);
    console.log('booking ' + id + ' renewed');
    return {text: 'ok'};
  }
  if (ev === 'renewal_failed') {
    // Stripe retries the card; the seat is kept meanwhile and the parent is asked to update the card.
    db.exec("UPDATE bookings SET sub_status = 'overdue' WHERE id = ?", id);
    if (o.status === 'confirmed') mail(db.query('SELECT * FROM bookings WHERE id = ?', id)[0], req.origin, 'overdue');
    console.log('booking ' + id + ' renewal failed');
    return {text: 'ok'};
  }
  if (ev === 'subscription_cancelled') {
    // The monthly enrolment has ended: the seat is free again.
    db.exec("UPDATE bookings SET sub_status = 'ended' WHERE id = ?", id);
    if (o.status === 'confirmed') {
      db.exec("UPDATE bookings SET status = 'completed' WHERE id = ?", id);
      const ended = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
      mail(ended, req.origin, 'ended');
      tellOwner(ended, 'Monthly enrolment ended', 'The subscription has ended and the seat is free again.');
    }
    console.log('booking ' + id + ' subscription ended');
    return {text: 'ok'};
  }
  if (ev === 'paid') {
    if (o.status === 'confirmed') return {text: 'ignored'};
    if (['pending', 'expired', 'failed'].indexOf(o.status) < 0) {
      // Paid after it was cancelled: give the money back at once; the owner is told either way.
      db.exec('UPDATE bookings SET paid_amount = ? WHERE id = ?', round2((o.paid_amount || 0) + (req.body.amount || 0)), id);
      const late = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
      const refunded = ['cancelled', 'refunded'].indexOf(o.status) >= 0 ? refundBooking(late, 'requested_by_customer') : 0;
      tellOwner(db.query('SELECT * FROM bookings WHERE id = ?', id)[0], 'Payment for a ' + o.status + ' booking', refunded > 0
        ? 'AED ' + money(refunded) + ' was paid by card after the booking was ' + o.status + ' and has been refunded automatically.'
        : 'AED ' + money(req.body.amount) + ' was paid by card after the booking was ' + o.status + '. Refund it on the Payments page or confirm the booking in the admin panel.');
      return {text: 'ok'};
    }
    // A payment that arrives after the one-hour hold may meet someone else in the same time or seat: the owner is told.
    const clash = (o.status !== 'pending' || o.created_at < holdSince()) ? clashOf(o) : '';
    db.exec("UPDATE bookings SET status = 'confirmed', paid_amount = ? WHERE id = ?", req.body.amount || o.deposit_due, id);
    if (sub) db.exec("UPDATE bookings SET sub_status = 'active', paid_until = ? WHERE id = ?", sub.current_period_end || '', id);
    const paid = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
    mail(paid, req.origin, 'email');
    tellOwner(paid, clash ? 'DOUBLE BOOKING, paid late' : 'New booking', clash ? 'This was paid after its hold ended and ' + clash + '. Call the customer to move it, or refund it on the Payments page.' : '');
  } else if (o.status === 'pending') {
    // Failed or expired: the booking no longer keeps its time or seat.
    db.exec('UPDATE bookings SET status = ? WHERE id = ?', ev === 'failed' ? 'failed' : 'expired', id);
  }
  console.log('booking ' + id + ' payment ' + ev);
  return {text: 'ok'};
}

scripts.daily_schedule:
// Job, every evening: expires bookings whose card payment never arrived, emails the owner tomorrow's schedule
// and emails each customer with a booking tomorrow a reminder (once). Class customers are reminded before their first session.
function handle(req) {
  const tomorrow = addDays(dubaiNow().date, 1), b = business();
  const expired = db.exec("UPDATE bookings SET status = 'expired' WHERE status = 'pending' AND created_at < ?", holdSince()).rowsAffected;
  const appts = db.query("SELECT * FROM bookings WHERE kind = 'appointment' AND date = ? AND status = 'confirmed' ORDER BY time, id LIMIT 150", tomorrow);
  const sessions = db.query('SELECT * FROM classes WHERE active = 1 AND weekday = ? ORDER BY time', weekday(tomorrow))
    .filter(c => !c.start_date || (c.start_date <= tomorrow && !classEnded(c, tomorrow)));
  const lines = appts.map(o => o.time + '-' + o.end_time + '  ' + o.item + ' with ' + o.staff_name + ': ' + o.customer_name + ', ' + o.phone +
    ' (to pay at the venue: AED ' + money(o.price - (o.paid_amount || 0)) + ')');
  if (sessions.length) {
    const names = {};
    for (const r of db.query("SELECT class_id, participant, sub_status FROM bookings WHERE kind = 'class' AND status = 'confirmed' ORDER BY id LIMIT 500")) {
      (names[r.class_id] = names[r.class_id] || []).push(r.participant + (r.sub_status === 'overdue' ? ' (monthly payment overdue)' : ''));
    }
    for (const c of sessions) {
      const list = names[c.id] || [];
      lines.push(c.time + '  ' + c.name + ' (class): ' + list.length + ' of ' + c.capacity + ' seats' + (list.length ? ': ' + list.join(', ') : ''));
    }
  }
  if (lines.length) {
    try {
      notify.owner({subject: 'Tomorrow: ' + appts.length + ' appointment' + (appts.length === 1 ? '' : 's') + ' and ' + sessions.length + ' class session' +
        (sessions.length === 1 ? '' : 's') + ' (' + dayName(tomorrow, 'en') + ' ' + tomorrow + ')', text: lines.join('\n')});
    } catch (e) { console.warn('owner not notified: ' + e); }
  }
  // At most 50 reminders a run keeps the job inside its time and database limits; the rest are not reminded.
  const due = db.query("SELECT * FROM bookings WHERE date = ? AND status = 'confirmed' AND email != '' AND coalesce(reminded, 0) = 0 ORDER BY id LIMIT 50", tomorrow);
  const t = {en: texts('en'), ar: texts('ar')};
  let sent = 0;
  for (const o of due) {
    if (mail(o, req.origin, 'reminder', b, t[o.lang === 'ar' ? 'ar' : 'en'])) sent++;
  }
  if (due.length) db.exec('UPDATE bookings SET reminded = 1 WHERE id IN (' + due.map(() => '?').join(', ') + ')', ...due.map(o => o.id));
  return {text: appts.length + ' appointments and ' + sessions.length + ' class sessions tomorrow; ' + sent + ' reminders sent; ' + expired + ' unpaid bookings expired'};
}

