scripts.stop_monthly:
// POST /bookings/:id/stop (signed in): the customer stops a monthly enrolment. The subscription ends at the end of the
// month already paid, so the seat is kept until then; on_payment then marks the enrolment completed and frees the seat.
function handle(req) {
  const lang = req.form.lang === 'ar' ? 'ar' : 'en', q = lang === 'ar' ? '&lang=ar' : '';
  const id = Number(req.params.id);
  const o = db.query('SELECT * FROM bookings WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!o) return {template: 'not_found', data: page(req, {title: texts(langOf(req)).not_found_title}), status: 404};
