scripts.admin_change:
// on_admin_change: runs right after the owner or staff adds or changes a booking in the admin panel.
// - A new staff member keeps the staff name in step; a new start time keeps the length of the appointment.
// - A new date, time or staff member (or class) is checked again for double booking; the owner is told if it clashes.
// - The customer is emailed in their language: a confirmation (confirmed), the cancellation with the refund (cancelled:
//   what was paid by card is refunded, a monthly subscription is stopped), a note on no_show and completed,
//   or the new date and time.
const STATUS_MAILS = {confirmed: 'email', cancelled: 'cancelled', no_show: 'no_show', completed: 'completed'};
function handle(req) {
  const ch = req.body;
  if (ch.table !== 'bookings' || ch.action === 'delete' || !ch.row) return {text: 'nothing to do'};
  const id = ch.id, was = ch.before || {}, inserted = ch.action === 'insert';
  let o = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
  if (!o) return {text: 'nothing to do'};
  if (o.kind === 'appointment' && o.staff_id && (inserted || o.staff_id !== was.staff_id)) {
    const s = db.query('SELECT name, name_ar FROM staff WHERE id = ?', o.staff_id)[0];
    if (s) db.exec('UPDATE bookings SET staff_name = ?, staff_name_ar = ? WHERE id = ?', s.name, s.name_ar || '', id);
  }
  if (!inserted && o.time !== was.time && o.end_time === was.end_time && was.time && was.end_time && /^\d{1,2}:\d{2}$/.test(String(o.time))) {
    db.exec('UPDATE bookings SET end_time = ? WHERE id = ?', hhmm(mins(o.time) + mins(was.end_time) - mins(was.time)), id);
  }
  o = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
  const moved = !inserted && ['date', 'time', 'end_time', 'staff_id', 'class_id'].some(k => String(o[k] || '') !== String(was[k] || ''));
  const newStatus = inserted ? '' : o.status !== was.status ? o.status : '';
  const out = [];
  const holds = o.status === 'confirmed' || o.status === 'pending';
  if (holds && (inserted || moved || newStatus === 'confirmed')) {
    const clash = clashOf(o);
    if (clash) {
      tellOwner(o, 'DOUBLE BOOKING after an admin change', 'Booking #' + o.id + ' ' + clash + '. Move one of them in the admin panel and the customer is emailed the new time.');
      out.push('double booking: ' + clash);
    }
  }
  if (newStatus === 'cancelled' && ['confirmed', 'pending'].indexOf(was.status) >= 0) {
    const refunded = refundBooking(o, 'requested_by_customer');
    if (refunded > 0) out.push('refunded AED ' + money(refunded));
    if (refunded < 0) tellOwner(o, 'Refund failed', 'AED ' + money(o.paid_amount) + ' was paid by card and could not be refunded automatically. Refund it on the Payments page or in Stripe.');
    o = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
  } else if (newStatus === 'completed' && isMonthly(o) && o.sub_status !== 'ended') {
    // The owner ends a monthly enrolment: no further months are charged.
    if (stopSubscription(o, true)) out.push('subscription stopped');
  }
  // One email per change: the new status (a confirmation shows the new time too), else the new time.
  let kind = '';
  if (inserted) kind = o.status === 'confirmed' ? 'email' : '';
  else if (newStatus === 'cancelled') kind = ['confirmed', 'pending'].indexOf(was.status) >= 0 ? 'cancelled' : '';
  else if (newStatus) kind = STATUS_MAILS[newStatus] || '';
  if (!kind && moved && holds) kind = 'changed';
  if (kind && mail(o, req.origin, kind)) out.push(kind + ' email sent');
  return {text: out.join('; ') || 'nothing to do'};
}

lib.booking:
// What is paid online: the deposit (business.deposit_percent of the price) by card, or nothing when paying at the venue.
// Monthly classes (classes.billing = 'monthly') are paid in full by card every month instead.
function terms(b, price, monthly) {
  const pct = Math.min(100, Math.max(0, Number(b.deposit_percent) || 0));
  const canCard = !!b.card_enabled && pct > 0 && price > 0;
  return {canCard: canCard, canVenue: !!b.pay_at_venue_enabled || !canCard, monthly: !!monthly,
    deposit: canCard ? (monthly ? round2(price) : round2(price * pct / 100)) : 0, full: !!monthly || pct >= 100};
}
function termsView(b, price_, monthly, t) {
  const x = terms(b, price_, monthly);
  return {canCard: x.canCard, canVenue: x.canVenue, monthly: x.monthly, deposit: price(x.deposit, t), full: x.full,
    balance: x.canCard && !x.full ? price(price_ - x.deposit, t) : ''};
}
// A monthly enrolment paid by card: a subscription with the reference booking-<id>.
function isMonthly(o) { return o.billing === 'monthly' && o.payment_method === 'card'; }
// Customers cancel on the site until business.cancellation_hours before the start. A running monthly enrolment
// is stopped instead (canStop), at the end of the month paid.
function canCancel(b, o) {
  if (o.status !== 'pending' && o.status !== 'confirmed') return false;
  if (isMonthly(o) && o.status === 'confirmed') return false;
  const d = o.date.split('-'), start = Date.UTC(Number(d[0]), Number(d[1]) - 1, Number(d[2])) + mins(o.time) * 60000;
  return start - (Date.now() + 4 * 3600 * 1000) >= (b.cancellation_hours || 0) * 3600 * 1000;
}
function canStop(o) { return isMonthly(o) && o.status === 'confirmed' && (o.sub_status === 'active' || o.sub_status === 'overdue'); }
// A bookings row for templates: amounts with their currency and dates in the page's language.
function view(o, lang, t, b) {
  const paid = o.paid_amount || 0, monthly = isMonthly(o), until = String(o.paid_until || '').slice(0, 10);
  const sub = monthly && o.sub_status ? String(t['sub_' + o.sub_status] || o.sub_status).split('{date}').join(longDate(until, t)) : '';
  return {id: o.id, no: String(t.booking_no).split('{id}').join(o.id), kind: o.kind, status: o.status, statusText: t['status_' + o.status] || o.status,
    bad: ['cancelled', 'failed', 'expired', 'no_show'].indexOf(o.status) >= 0, item: pick(o, 'item', lang),
    staff: pick(o, 'staff_name', lang) || '', participant: o.participant || '', date: o.date, dateText: longDate(o.date, t), day: dayName(o.date, lang),
    time: o.time, end: o.end_time || '', booked: longDate(o.created_at, t), bookedOn: String(o.created_at || '').slice(0, 10),
    price: price(o.price, t), deposit: price(o.deposit_due, t), paid: price(paid, t), vat: price(o.vat, t),
    balance: price(monthly ? 0 : o.status === 'pending' ? o.price - o.deposit_due : o.status === 'confirmed' ? o.price - paid : 0, t),
    method: o.payment_method === 'card' ? (monthly ? t.pay_monthly_card : t.pay_card) : t.pay_venue, name: o.customer_name, phone: o.phone,
    priceNote: o.billing === 'monthly' ? t.per_month : '', sub: sub, overdue: monthly && o.sub_status === 'overdue',
    refunded: (o.refunded_amount || 0) > 0 ? price(o.refunded_amount, t) : '',
    canPay: o.status === 'pending' && o.payment_method === 'card', canCancel: canCancel(b, o), canStop: canStop(o), until: until,
    open: o.status === 'pending' || o.status === 'confirmed',
    hasReceipt: ['confirmed', 'completed', 'no_show', 'refunded'].indexOf(o.status) >= 0};
}

// Records a refund of one card payment (payment id -> refunded so far, kept in bookings.refunds) and keeps paid_amount
// and refunded_amount in step. Safe to call twice for the same refund, as on_payment does when the refund event arrives.
// Returns the amount newly refunded.
function recordRefund(id, paymentId, refundedSoFar) {
  const o = db.query('SELECT paid_amount, refunds FROM bookings WHERE id = ?', id)[0];
  if (!o) return 0;
  let m = {};
  try { m = JSON.parse(o.refunds || '{}') || {}; } catch (e) { m = {}; }
  const delta = round2(Math.max(0, (refundedSoFar || 0) - (m[paymentId] || 0)));
  m[paymentId] = Math.max(m[paymentId] || 0, refundedSoFar || 0);
  let total = 0;
  for (const k in m) total += m[k];
  db.exec('UPDATE bookings SET refunds = ?, refunded_amount = ?, paid_amount = ? WHERE id = ?', JSON.stringify(m), round2(total),
    round2(Math.max(0, (o.paid_amount || 0) - delta)), id);
  return delta;
}
// Stops a monthly enrolment's subscription now (stopNow) or at the end of the month paid. Returns true when stopped.
function stopSubscription(o, stopNow) {
  const ref = 'booking-' + o.id;
  try {
    const s = payments.subscription(ref);
    if (!s || s.status === 'canceled' || s.status === 'pending') return false;
    payments.cancel_subscription({reference: ref, at_period_end: !stopNow});
    db.exec('UPDATE bookings SET sub_status = ? WHERE id = ?', stopNow ? 'ended' : 'ending', o.id);
    return true;
  } catch (e) { console.warn('subscription of booking ' + o.id + ' not stopped: ' + e); return false; }
}
// Gives back what was paid by card: everything not refunded yet (the deposit or the full price), or for a monthly
// enrolment the newest month, after stopping its subscription. Returns the amount refunded, or -1 when the refund
// failed (the owner then refunds by hand).
function refundBooking(o, reason) {
  if (o.payment_method !== 'card') return 0;
  if (isMonthly(o)) stopSubscription(o, true);
  if ((o.paid_amount || 0) <= 0) return 0;
  try {
    const r = payments.refund({reference: 'booking-' + o.id, reason: reason || 'requested_by_customer'});
    return recordRefund(o.id, r.id, r.refunded_amount);
  } catch (e) { console.warn('booking ' + o.id + ' not refunded: ' + e); return -1; }
}

// After a booking row is created: pay-at-venue bookings are confirmed already; card bookings go to the payment page,
// monthly classes to a monthly card subscription.
function proceed(req, id, lang) {
  const o = db.query('SELECT * FROM bookings WHERE id = ?', id)[0];
  const q = lang === 'ar' ? '&lang=ar' : '';
  if (o.payment_method !== 'card') {
    mail(o, req.origin, 'email');
    tellOwner(o, 'New booking');
    return {redirect: '/bookings/' + id + '?placed=1' + q};
  }
  const pay = {reference: 'booking-' + id, customer_email: o.email || '',
    success_path: '/bookings/' + id + '?placed=1' + q, cancel_path: '/bookings/' + id + (lang === 'ar' ? '?lang=ar' : '')};
  try {
    let res;
    if (isMonthly(o)) {
      pay.items = [{name: o.item + (o.participant ? ' (' + o.participant + ')' : '') + ', monthly', price: o.deposit_due, quantity: 1}];
      pay.interval = 'month';
      res = payments.subscribe(pay);
    } else {
      pay.items = [{name: o.item + ', ' + o.date + ' ' + o.time + (o.deposit_due < o.price ? ' (deposit)' : ''), price: o.deposit_due, quantity: 1}];
      res = payments.checkout(pay);
    }
    return {redirect: res.url};
  } catch (e) {
    console.error('checkout failed for booking ' + id + ': ' + e);
    db.exec("UPDATE bookings SET status = 'failed' WHERE id = ?", id);
    return {redirect: '/bookings/' + id + '?error=error_payment' + q};
  }
}

lib.common:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function business() { return db.query('SELECT * FROM business ORDER BY id LIMIT 1')[0]; }
function round2(n) { return Math.round(n * 100) / 100; }
function money(n) { return round2(n || 0).toFixed(2); }
// An amount with its currency in the page's language, from texts.money: "AED 250.00" or "250.00 د.إ".
function price(n, t) { return (t.money || 'AED {n}').replace('{n}', money(n)); }
// The same for notes and sentences: whole amounts without decimals ("AED 200"), kept on one line.
function amount(n, t) { const v = round2(n || 0); return (t.money || 'AED {n}').replace('{n}', v % 1 === 0 ? String(v) : v.toFixed(2)).replace(/ /g, '\u00a0'); }
// 'YYYY-MM-DD' as "19 Nov 2026" or "19 نوفمبر 2026" (month names from texts.months, Western digits).
function longDate(ymd, t) {
  const p = String(ymd || '').slice(0, 10).split('-'), m = String(t.months || '').split('|');
  if (p.length !== 3 || m.length !== 12) return String(ymd || '');
  return Number(p[2]) + ' ' + m[Number(p[1]) - 1] + ' ' + p[0];
}
// The Arabic value of a column pair such as name / name_ar, or the English one when there is none.
function pick(row, field, lang) { return lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]; }
// The current address in the other language, keeping the other query parameters (error, placed).
function langLink(req, lang) {
  const q = [];
  for (const k in req.query) if (k !== 'lang') q.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  if (lang === 'ar') q.push('lang=ar');
  return req.path + (q.length ? '?' + q.join('&') : '');
}
function page(req, extra) {
  const lang = langOf(req), b = business(), t = texts(lang), err = String(req.query.error || '');
  const qs = lang === 'ar' ? '?lang=ar' : '';
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: t, user: req.user,
    biz: b, theme: theme(b), bizName: pick(b, 'name', lang), tagline: pick(b, 'tagline', lang), story: pick(b, 'story', lang) || '',
    address: pick(b, 'address', lang) || '', path: req.path, qs: qs, amp: lang === 'ar' ? '&lang=ar' : '', here: req.path + qs,
    langEn: langLink(req, 'en'), langAr: langLink(req, 'ar'), wa: (b.whatsapp || '').replace(/[^0-9]/g, ''),
    hours: String(t.open_daily).split('{opens}').join(b.opens).split('{closes}').join(b.closes),
    error: err.indexOf('error_') === 0 && t[err] ? t[err] : ''};
  for (const k in extra) base[k] = extra[k];
  return base;
}

// Dates and times are UAE local time (UTC+4 all year, no daylight saving), kept as text: 'YYYY-MM-DD' and 'HH:MM'.
const DAYS = {en: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
  ar: ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت']};
function dubaiNow() { const s = new Date(Date.now() + 4 * 3600 * 1000).toISOString(); return {date: s.slice(0, 10), time: s.slice(11, 16)}; }
function addDays(date, n) { const p = date.split('-'); return new Date(Date.UTC(Number(p[0]), Number(p[1]) - 1, Number(p[2]) + n)).toISOString().slice(0, 10); }
function validDate(date) { return /^\d{4}-\d{2}-\d{2}$/.test(String(date)) && addDays(date, 0) === date; }
function weekday(date) { const p = date.split('-'); return new Date(Date.UTC(Number(p[0]), Number(p[1]) - 1, Number(p[2]))).getUTCDay(); }
function dayName(date, lang) { return DAYS[lang === 'ar' ? 'ar' : 'en'][weekday(date)]; }
function mins(t) { const p = String(t).split(':'); return Number(p[0]) * 60 + Number(p[1] || 0); }
function hhmm(m) { const h = Math.floor(m / 60), r = m % 60; return (h < 10 ? '0' : '') + h + ':' + (r < 10 ? '0' : '') + r; }
// 'YYYY-MM-DD' as "Thu 20 Nov" / "خميس 20 نوفمبر", for the date picker.
function shortDay(date, t) {
  const p = date.split('-'), m = String(t.months || '').split('|'), w = String(t.days_short || '').split('|');
  return (w[weekday(date)] || '') + ' ' + Number(p[2]) + ' ' + (m[Number(p[1]) - 1] || '');
}

lib.notify:
// Emails the customer in the booking's language, from the texts <kind>_subject and <kind>_body: 'email' (confirmation),
// 'reminder', 'changed' (new date, time or staff), 'cancelled', 'no_show', 'completed', 'overdue' and 'ended' (monthly).
// Formatted as on the booking page: {date} "Thursday 19 Nov 2026" / "الخميس 19 نوفمبر 2026", {time} the start (HH:MM),
// {times} start to end (texts.email_time_range), amounts "AED 150.00" / "150.00 د.إ". Quiet on failure.
function mail(o, origin, kind, b, t) {
  if (!o.email) return false;
  const lang = o.lang === 'ar' ? 'ar' : 'en';
  b = b || business(); t = t || texts(lang);
  const details = [];
  if (o.staff_name) details.push(String(t.with_staff).split('{staff}').join(pick(o, 'staff_name', lang)));
  if (o.participant) details.push(t.participant + ': ' + o.participant);
  const paid = o.paid_amount || 0;
  const times = o.end_time ? String(t.email_time_range).split('{start}').join(o.time).split('{end}').join(o.end_time) : o.time;
  const vals = {id: o.id, business: pick(b, 'name', lang), item: pick(o, 'item', lang), date: dayName(o.date, lang) + ' ' + longDate(o.date, t), time: o.time,
    times: times, details: details.join('\n'), price: price(o.price, t), paid: price(paid, t), due: price(Math.max(0, o.price - paid), t),
    address: pick(b, 'address', lang) || '', link: origin + '/bookings/' + o.id + (lang === 'ar' ? '?lang=ar' : ''),
    until: longDate(String(o.paid_until || '').slice(0, 10), t),
    refund: (o.refunded_amount || 0) > 0 ? '\n' + String(t.refund_line).split('{amount}').join(price(o.refunded_amount, t)) : ''};
  const fill = (s) => { s = String(s || ''); for (const k in vals) s = s.split('{' + k + '}').join(String(vals[k])); return s; };
  try { email.send({to: o.email, subject: fill(t[kind + '_subject']), text: fill(t[kind + '_body'])}); return true; }
  catch (e) { console.warn(kind + ' not sent for booking ' + o.id + ': ' + e); return false; }
}
// Tells the owner by email (and WhatsApp, if turned on): the essentials are in the subject.
function tellOwner(o, what, extra) {
  let pay = o.payment_method === 'card' ? 'AED ' + money(o.paid_amount || 0) + ' paid by card' : 'pay at venue AED ' + money(o.price);
  if (isMonthly(o)) pay += ' (monthly AED ' + money(o.price) + ')';
  if ((o.refunded_amount || 0) > 0) pay += ', AED ' + money(o.refunded_amount) + ' refunded';
  const who = o.kind === 'class' ? (o.participant || '') : (o.staff_name || '');
  let subject = what + ' #' + o.id + ': ' + o.item + ', ' + dayName(o.date, 'en').slice(0, 3) + ' ' + o.date + ' ' + o.time + (who ? ', ' + who : '') + ', ' + pay;
  if (subject.length > 150) subject = subject.slice(0, 147) + '...';
  try {
    notify.owner({subject: subject, text: 'Customer: ' + o.customer_name + ', ' + o.phone + (o.email ? ', ' + o.email : '') +
      (o.participant ? '\nParticipant: ' + o.participant : '') + '\nPrice: AED ' + money(o.price) + '\nPaid online: AED ' + money(o.paid_amount || 0) + (extra ? '\n\n' + extra : '')});
  } catch (e) { console.warn('owner not notified: ' + e); }
}

lib.slots:
// A booking keeps its time or seat while it is confirmed, or pending (waiting for the card payment) for at most an hour.
const HOLDS = "(status = 'confirmed' OR (status = 'pending' AND created_at >= ?))";
function holdSince() { return new Date(Date.now() - 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19); }

// Staff who do a service: staff.services is a comma list of service ids, empty for all.
function staffFor(service) {
  return db.query('SELECT * FROM staff WHERE active = 1 ORDER BY id').filter(s => {
    const ids = String(s.services || '').split(',').map(x => x.trim()).filter(Boolean);
    return ids.length === 0 || ids.indexOf(String(service.id)) >= 0;
  });
}
// Free start times of a service on a date: [{time: 'HH:MM', staff: [ids of free staff]}]. staffId 0 means anyone.
// Built from the opening hours, the service's duration and the bookings each staff member already has.
function freeSlots(b, service, staffId, date, exceptBooking) {
  const now = dubaiNow();
  if (!validDate(date) || date < now.date || date > addDays(now.date, b.days_ahead || 30)) return [];
  if (String(b.closed_days || '').split(',').map(x => x.trim()).indexOf(String(weekday(date))) >= 0) return [];
  let staff = staffFor(service);
  if (staffId) staff = staff.filter(s => s.id === staffId);
  if (staff.length === 0) return [];
  const busy = {};
  for (const r of db.query("SELECT id, staff_id, time, end_time FROM bookings WHERE kind = 'appointment' AND date = ? AND " + HOLDS, date, holdSince())) {
    if (r.id === exceptBooking) continue;
    (busy[r.staff_id] = busy[r.staff_id] || []).push([mins(r.time), mins(r.end_time)]);
  }
  const open = mins(b.opens || '09:00'), close = mins(b.closes || '18:00'), step = Math.max(5, b.slot_minutes || 30);
  const earliest = date === now.date ? mins(now.time) : -1;
  const out = [];
  for (let m = open; m + service.duration_min <= close; m += step) {
    if (m <= earliest) continue;
    const end = m + service.duration_min;
    const free = staff.filter(s => !(busy[s.id] || []).some(x => m < x[1] && end > x[0])).map(s => s.id);
    if (free.length) out.push({time: hhmm(m), staff: free});
  }
  return out;
}

// Classes: weekly on classes.weekday; start_date is optional (empty: runs every week, join any time).
function nextOn(wd, after) { for (let i = 1; i <= 7; i++) { const d = addDays(after, i); if (weekday(d) === wd) return d; } return after; }
function classFirstDate(c, today) { return c.start_date && c.start_date > today ? c.start_date : nextOn(c.weekday, today); }
function classEnded(c, today) { return !!c.start_date && validDate(c.start_date) && addDays(c.start_date, 7 * (Math.max(1, c.sessions) - 1)) < today; }
// Seats taken per class id.
function seatsTaken(exceptBooking) {
  const m = {};
  for (const r of db.query("SELECT class_id, COUNT(*) AS n FROM bookings WHERE kind = 'class' AND id != ? AND " + HOLDS + " GROUP BY class_id", exceptBooking || 0, holdSince())) m[r.class_id] = r.n;
  return m;
}
function classView(c, lang, t, taken, today) {
  const left = Math.max(0, c.capacity - (taken[c.id] || 0));
  const starts = c.start_date && c.start_date > today ? c.start_date : '';
  return {id: c.id, name: pick(c, 'name', lang), description: pick(c, 'description', lang), age: pick(c, 'age_group', lang) || '',
    day: DAYS[lang][c.weekday] || '', time: c.time, end: hhmm(mins(c.time) + c.duration_min), sessions: c.sessions,
    starts: starts, startsText: starts ? longDate(starts, t) : '', price: price(c.price, t), image: c.image,
    monthly: c.billing === 'monthly', priceNote: c.billing === 'monthly' ? t.per_month : t.term_price,
    left: left, full: left === 0, leftText: left === 0 ? t.class_full : left === 1 && t.seat_left ? t.seat_left : String(t.seats_left).split('{n}').join(left),
    ended: classEnded(c, today)};
}


// Another booking that holds the same time with the same staff member, or the seat count when a class is over capacity.
// Used when a time changes after booking: a late payment or an owner's change in the admin panel. Returns a text or ''.
function clashOf(o) {
  if (o.kind === 'class') {
    const c = db.query('SELECT name, capacity FROM classes WHERE id = ?', o.class_id)[0];
    if (!c) return 'class #' + o.class_id + ' no longer exists';
    const n = (seatsTaken(o.id)[o.class_id] || 0) + 1;
    return n > c.capacity ? n + ' enrolments for ' + c.capacity + ' seats in ' + c.name : '';
  }
  const other = db.query("SELECT id, customer_name, time, end_time FROM bookings WHERE kind = 'appointment' AND staff_id = ? AND date = ? AND id != ? AND time < ? AND end_time > ? AND " + HOLDS,
    o.staff_id, o.date, o.id, o.end_time, o.time, holdSince())[0];
  return other ? 'overlaps booking #' + other.id + ' (' + other.customer_name + ', ' + other.time + '-' + other.end_time + ')' : '';
}

lib.theme:
// Merchant branding from the settings row (brand_color, font, logo), shared by every Renoxium template.
// theme(row) returns {brand, onBrand, brandText, font, style, lux, logo}; the "top" template puts them on <html>
// (data-font, data-style and CSS variables).
// brand: the owner's colour (#rrggbb); when it is empty or not a colour, a quiet slate (or a deep ink for the luxury styles).
// onBrand: white or near-black, whichever reads better on brand (buttons, the intro band).
// brandText: brand darkened until it passes WCAG AA (4.5:1) as text on white, for links and selected states.
// font picks the type pair and the style:
//   modern (IBM Plex Sans + IBM Plex Sans Arabic), classic (Markazi Text headings + IBM Plex), rounded (Rubik): style "standard".
//   heritage (Cormorant Garamond + Jost, Amiri + Noto Naskh Arabic; ivory, antique gold hairlines) and
//   atelier (Bodoni Moda + Hanken Grotesk, Noto Naskh Arabic + Noto Kufi Arabic; white, near monochrome): style "luxury",
//   which switches to the luxury layout (centred name, full-bleed photo, no boxes, square buttons).
const THEME_DEFAULT_BRAND = '#334155';
const THEME_DEFAULT_INK = '#1f1b17';
const THEME_FONTS = ['modern', 'classic', 'rounded', 'heritage', 'atelier'];
const THEME_LUXURY = ['heritage', 'atelier'];
function themeHex(v) {
  let s = String(v || '').trim().toLowerCase();
  if (/^#?[0-9a-f]{3}$/.test(s)) s = s.replace('#', '').split('').map(c => c + c).join('');
  s = s.replace('#', '');
  return /^[0-9a-f]{6}$/.test(s) ? '#' + s : '';
}
function themeRgb(hex) { return [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); }
function themeLum(rgb) {
  const c = rgb.map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function themeContrast(a, b) { const x = themeLum(a), y = themeLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function themeToHex(rgb) { return '#' + rgb.map(v => (Math.round(v) < 16 ? '0' : '') + Math.round(v).toString(16)).join(''); }
function theme(row) {
  row = row || {};
  const font = THEME_FONTS.indexOf(row.font) >= 0 ? row.font : 'modern';
  const lux = THEME_LUXURY.indexOf(font) >= 0;
  const brand = themeHex(row.brand_color) || (lux ? THEME_DEFAULT_INK : THEME_DEFAULT_BRAND);
  const rgb = themeRgb(brand), white = [255, 255, 255], ink = [26, 23, 22];
  const onBrand = themeContrast(rgb, white) >= themeContrast(rgb, ink) ? '#ffffff' : '#1a1716';
  let text = rgb;
  for (let i = 0; i < 20 && themeContrast(text, white) < 4.5; i++) text = text.map(v => v * 0.9);
  return {brand: brand, onBrand: onBrand, brandText: themeToHex(text), font: font, style: lux ? 'luxury' : 'standard', lux: lux, logo: row.logo || ''};
}
